param([Parameter(Mandatory=$true)][string]$RunRoot,[Parameter(Mandatory=$true)][string]$WorkingDirectory,[Parameter(Mandatory=$true)][string[]]$SourcePaths)
$ErrorActionPreference='Stop'; $RunRoot=[IO.Path]::GetFullPath($RunRoot);$cwd=[IO.Path]::GetFullPath($WorkingDirectory);$env:M0_RUN_EVIDENCE_ROOT=$RunRoot;$id=Split-Path -Leaf $RunRoot;$out=Join-Path $RunRoot 'build';New-Item -ItemType Directory -Path $out -Force|Out-Null
function Head { $h=& git -C $cwd rev-parse HEAD;if($LASTEXITCODE -ne 0){throw 'git rev-parse failed'};return $h.Trim() }
function Snap([string]$name){$rows=@(foreach($rel in $SourcePaths){$p=Join-Path $cwd $rel;$b=[IO.File]::ReadAllBytes($p);$lf=[Text.Encoding]::UTF8.GetBytes([Text.Encoding]::UTF8.GetString($b).Replace("`r`n","`n"));$blob=& git -C $cwd hash-object -- $rel;if($LASTEXITCODE -ne 0){throw 'git hash-object failed'};[pscustomobject]@{path=$rel;size=$b.Length;sha256=([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($b)).ToLowerInvariant());lf_sha256=([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($lf)).ToLowerInvariant());git_blob=$blob.Trim()}});$rows|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $out "$name-source.json") -Encoding utf8;return ,$rows }
$started=[DateTime]::UtcNow.ToString('o');$headBefore=Head;$before=Snap 'before';$psi=[Diagnostics.ProcessStartInfo]::new('cmd.exe');$psi.WorkingDirectory=$cwd;$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;foreach($a in @('/d','/c','npm.cmd run build')){$psi.ArgumentList.Add($a)};$proc=[Diagnostics.Process]::Start($psi);$ot=$proc.StandardOutput.ReadToEndAsync();$et=$proc.StandardError.ReadToEndAsync();$proc.WaitForExit();$exit=$proc.ExitCode;$stdout=$ot.GetAwaiter().GetResult();$stderr=$et.GetAwaiter().GetResult();[IO.File]::WriteAllText((Join-Path $out 'stdout.txt'),$stdout,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $out 'stderr.txt'),$stderr,[Text.UTF8Encoding]::new($false));$after=Snap 'after';$headAfter=Head;$finished=[DateTime]::UtcNow.ToString('o')
$record=[ordered]@{kind='Build';capture_id=$id;cwd=$cwd;evidence_root=$RunRoot;command='npm.cmd run build';started_utc=$started;finished_utc=$finished;actual_head_before=$headBefore;actual_head_after=$headAfter;exit_code=$exit;stdout=(Join-Path $out 'stdout.txt');stderr=(Join-Path $out 'stderr.txt')}
if($exit -eq 0){$dist=Join-Path $cwd 'dist/etl-worker/snapshot-apply-worker.js';$bytes=[IO.File]::ReadAllBytes($dist);$manifest=[ordered]@{format='Fix1 build output manifest v1';capture_id=$id;manifest_created_utc=[DateTime]::UtcNow.ToString('o');actual_head_before=$headBefore;actual_head_after=$headAfter;cwd=$cwd;command='npm.cmd run build';started_utc=$started;build_finished_utc=$finished;exit_code=$exit;output=[ordered]@{path=[IO.Path]::GetFullPath($dist);size=$bytes.Length;sha256=([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes)).ToLowerInvariant())};source_files=$SourcePaths;before_source_file=(Join-Path $out 'before-source.json');after_source_file=(Join-Path $out 'after-source.json')};$mp=Join-Path $out 'build-output-manifest.json';$manifest|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $mp -Encoding utf8;$manifestHash=(Get-FileHash -Algorithm SHA256 -LiteralPath $mp).Hash.ToLowerInvariant();[IO.File]::WriteAllText("$mp.sha256",$manifestHash+"`n",[Text.UTF8Encoding]::new($false));$record.build_output_manifest=$mp;$record.build_output_manifest_sha256=$manifestHash;$record.output_path=$manifest.output.path;$record.output_size=$manifest.output.size;$record.output_sha256=$manifest.output.sha256}
$record|ConvertTo-Json -Depth 6|Set-Content -LiteralPath (Join-Path $out 'command.json') -Encoding utf8;"CAPTURED build id=$id exit=$exit HEAD=$headBefore";Get-Content -LiteralPath (Join-Path $out 'stdout.txt');if($stderr){[Console]::Error.WriteLine($stderr)};exit $exit
